import { action, observable, makeObservable } from "mobx";
import ajax from "@/utils/ajax";
import { lookupConfig } from "@/types/function";

function getParamsKey(params = {}){
    return Object.keys(params).map((key) => {
        if(!params[key]) params[key] = "";
        return `${key}=${params[key] || ''}`;
    }).join('&')
}

class Lookup {
    @observable lookups = null;

    items = {};

    key = action((code, parameters)=>{
        const key = `code=${code}&${getParamsKey(parameters)}`;
        // console.log(key);
        if(!this.items[key]){
            this.items[key] = observable.array([]);
            ajax.post('/custom/common/dataStorage/getDataStorageDetails', {code, parameters}).then(
                action((data) =>{
                    this.items[key].replace(data)
                })
            );
        }
        return this.items[key];
    })

    // 查找项返回promise
    key2 = action((code, parameters)=>{
        const key = `code=${code}&${getParamsKey(parameters)}`;
        this.items[key] = observable.array([]);
        return ajax.post('/custom/common/dataStorage/getDataStorageDetails', {code, parameters})
    })

    all = ()=>{
        if(!this.lookups){
            this.lookups = observable([]);
            ajax.get('/custom/common/dataStorage/getDataStorageConfig').then(
                action((data) => this.lookups = data)
            );
        }
        return this.lookups;
    }
    getParameters = (value)=>{
        const item = this.lookups?.find((item) => item.value === value);
        return item?.parameters;
    }

    constructor() {
        makeObservable(this);
    }
}

export default new Lookup();


export const featchData = () => {

    const lookup = new Lookup();
    return (config: lookupConfig) => {
        const { type, code, params } = config;
        if(type === "lookup"){
            if(code){
                return lookup.key(code, params);
            }
        }
    }
}