import _ from 'lodash';
import ajax from '@/utils/ajax';
import lookup, { featchData } from './lookup'
import classNames from 'classnames';
import { Message } from "@arco-design/web-react";
import { convertToTree, getSpecificValues, loadScript } from '@/utils';
import { showMessage, confirm } from './message';

export function isFunction(val): boolean {
    return typeof val === 'function';
}

export function isPromise(val): boolean {
    return typeof val === 'object' && isFunction(val.then) && isFunction(val.catch) && isFunction(val.finally);
}
export default {
    lookup,
    featchData,
    isPromise,
    ajax,
    history: { goBack:() => null, go: () => null, push: () => null, replace: () => null} as any,
    showMessage,
    confirm,
    classNames,
    getUuid:(type?: "hash") => {
        function S4() {
          return (((1 + Math.random()) * 0x10000) | 0).toString(16).substring(1);
        }
        if(type === "hash") return `${S4()}${S4()}`;
        return S4() + '-' + S4() + '-' + S4() + '-' + S4();
    },
    loadCSS(url: string) {
        var link = document.createElement('link');
        link.rel = 'stylesheet';
        link.type = 'text/css';
        link.href = url;
        document.head.appendChild(link);
    },
    loadScript,
    convertToTree,
    getSpecificValues,
}
