import { ReactNode } from 'react';
import { Message, Modal } from '@arco-design/web-react';
import { isPromise } from '@/utils/is';


type MessageType = "success" | "info" | "warning" | "error"

export const showMessage = (content: string, MessageType: MessageType = "success") => {
    Message[MessageType](content);
}

interface ConfirmProps {
    title: ReactNode;
    content: ReactNode;
    onCancel: () => void;
    onOk: () => void | (() => Promise<any>)
}

type ConfirmType = "confirm" | "info" | "success" | "warning" | "error";
export const confirm = (option: ConfirmProps, confirmType: ConfirmType = "confirm") => {
    return new Promise((resolve, reject) => {
        Modal[confirmType]({
            ...option,
            onCancel: () => {
                reject()
                if(option.onCancel) option.onCancel();
            },
            onOk: () => {
                if(option.onOk) {
                    const resultFun: any = option.onOk();
                    if(isPromise(resultFun)) {
                        return resultFun.then(resolve).catch(reject);
                    }else {
                        resolve(true)
                    }
                }else {
                    resolve(true)
                }
            }
        })
    })
}